/* Typedef for Register: hsp_cmd::HSSHA::CMD_CODE                          */
/* Title: SHA Command Codes                                                */
typedef union {
   struct {

      /* Title: load_digest                                                */
      /* Description:                                                      */
      /**
       *    Load a previous SHA digest from address based on the
       *    *SHA_CMD_INIT pointer in the command structure.
      */
      uint32_t load_digest : 1; /* bit 0; R/W */

      /* Description:                                                      */
      /**
       *    Reserved - unused bits.
      */
      uint32_t rsvd_3_1 : 3; /* bits 3 to 1; R; 0x0 */

      /* Title: dont_truncate                                              */
      /* Description:                                                      */
      /**
       *    Affects the digest written out to memory for certain modes
       *    (SHA-1, SHA-224, SHA-384, SHA-512/224, SHA-512/256). This
       *    parameter should be set when digest written out is to be used in
       *    future with load_digest for those modes. 1’b0 (default): the
       *    digest size is per NIST standard for the given sha_mode. 1’b1:
       *    the digest written out to memory is same size as working variable
       *     for the given sha_mode. Sizes of working variable is 160-bits
       *    for SHA-1 mode; 256-bits for SHA-224, SHA-256 modes; 512-bits for
       *     all other modes.
      */
      uint32_t dont_truncate : 1; /* bit 4; R/W */

      /* Description:                                                      */
      /**
       *    Reserved - unused bits.
      */
      uint32_t rsvd_7_5 : 3; /* bits 7 to 5; R; 0x0 */

      /* Title: auto_pad                                                   */
      /* Description:                                                      */
      /**
       *    Enable auto pad
      */
      uint32_t auto_pad : 1; /* bit 8; R/W */

      /* Title: read_message_mode                                          */
      /* Description:                                                      */
      /**
       *    Input Message addressing mode. 0: Increment mode, 1-3: Reserved
      */
      uint32_t read_message_mode : 2; /* bits 10 to 9; R/W */

      /* Description:                                                      */
      /**
       *    Reserved - unused bits.
      */
      uint32_t rsvd_15_11 : 5; /* bits 15 to 11; R; 0x00 */

      /* Title: sha_mode                                                   */
      /* Description:                                                      */
      /**
       *    SHA mode and length
      */
      uint32_t sha_mode : 4; /* bits 19 to 16; R/W */

      /* Title: digest_byte_swap                                           */
      /* Description:                                                      */
      /**
       *    Endianness of the digest when it's written out to memory, and the
       *     format of reference digest. 0(default): The first byte of digest
       *     is located at lowest address, 1: The byte location is swap
       *    within the field (Field is 32-bit for SHA-1, SHA-224 and SHA-256
       *    modes; 64-bit for rest.
      */
      uint32_t digest_byte_swap : 1; /* bit 20; R/W */

      /* Title: check_digest                                               */
      /* Description:                                                      */
      /**
       *    Compare and check computed digest against a reference digest
      */
      uint32_t check_digest : 1; /* bit 21; R/W */

      /* Title: pass_message_mode                                          */
      /* Description:                                                      */
      /**
       *    Message pass-through addressing mode, determines whether message
       *    data is reflected back out, and what addressing mode is used. 0:
       *    No pass-through. 1: Increment pass-through. 2-3: Reserved.
      */
      uint32_t pass_message_mode : 2; /* bits 23 to 22; R/W */

      /* Description:                                                      */
      /**
       *    Reserved - unused bits.
      */
      uint32_t rsvd_27_24 : 4; /* bits 27 to 24; R; 0x0 */

      /* Title: id                                                         */
      /* Description:                                                      */
      /**
       *    SHA Command Identifier
      */
      uint32_t id : 4; /* bits 31 to 28; R; 0x3 */
   };
   uint32_t AsUINT32;
} Hsp_cmd_HSSHA_CMD_CODE, *PHsp_cmd_HSSHA_CMD_CODE;
